describe('Change Email Address with Confirmation', () => {
  const testEmail = 'newemail@example.com';
  const confirmationCode = '123456';
  const invalidEmail = 'invalid-email';

  beforeEach(() => {
    cy.visit('/profile');
    cy.login('testuser@example.com', 'password123');
    cy.get('[data-testid="profile-page"]').should('be.visible');
  });

  it('should successfully change email address with valid confirmation', () => {
    // Navigate to email change section
    cy.get('[data-testid="edit-email-button"]').click();
    cy.get('[data-testid="email-change-modal"]').should('be.visible');

    // Enter new email address
    cy.get('[data-testid="new-email-input"]').clear().type(testEmail);
    cy.get('[data-testid="email-change-submit"]').click();

    // Verify confirmation step appears
    cy.get('[data-testid="confirmation-step"]').should('be.visible');
    cy.get('[data-testid="confirmation-message"]').should('contain', 'confirmation code');

    // Enter confirmation code
    cy.get('[data-testid="confirmation-code-input"]').type(confirmationCode);
    cy.get('[data-testid="confirm-email-button"]').click();

    // Verify success message and email update
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Email updated successfully');
    cy.get('[data-testid="current-email"]').should('contain', testEmail);

    // Verify modal closes
    cy.get('[data-testid="email-change-modal"]').should('not.exist');
  });

  it('should reject invalid email format', () => {
    // Navigate to email change section
    cy.get('[data-testid="edit-email-button"]').click();
    cy.get('[data-testid="email-change-modal"]').should('be.visible');

    // Enter invalid email
    cy.get('[data-testid="new-email-input"]').clear().type(invalidEmail);
    cy.get('[data-testid="email-change-submit"]').click();

    // Verify error message appears
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="email-error-message"]').should('contain', 'valid email address');

    // Verify confirmation step does not appear
    cy.get('[data-testid="confirmation-step"]').should('not.exist');
  });

  it('should handle incorrect confirmation code', () => {
    // Navigate to email change section
    cy.get('[data-testid="edit-email-button"]').click();
    cy.get('[data-testid="new-email-input"]').clear().type(testEmail);
    cy.get('[data-testid="email-change-submit"]').click();

    // Wait for confirmation step
    cy.get('[data-testid="confirmation-step"]').should('be.visible');

    // Enter incorrect confirmation code
    cy.get('[data-testid="confirmation-code-input"]').type('000000');
    cy.get('[data-testid="confirm-email-button"]').click();

    // Verify error message
    cy.get('[data-testid="confirmation-error"]').should('be.visible');
    cy.get('[data-testid="confirmation-error"]').should('contain', 'Invalid confirmation code');

    // Verify email was not changed
    cy.get('[data-testid="current-email"]').should('not.contain', testEmail);
  });

  it('should allow resending confirmation code', () => {
    // Navigate to email change section
    cy.get('[data-testid="edit-email-button"]').click();
    cy.get('[data-testid="new-email-input"]').clear().type(testEmail);
    cy.get('[data-testid="email-change-submit"]').click();

    // Wait for confirmation step
    cy.get('[data-testid="confirmation-step"]').should('be.visible');

    // Click resend code button
    cy.get('[data-testid="resend-code-button"]').click();

    // Verify resend success message
    cy.get('[data-testid="resend-success-message"]').should('be.visible');
    cy.get('[data-testid="resend-success-message"]').should('contain', 'code sent');

    // Verify confirmation input is still available
    cy.get('[data-testid="confirmation-code-input"]').should('be.visible');
  });

  it('should cancel email change and return to profile', () => {
    // Navigate to email change section
    cy.get('[data-testid="edit-email-button"]').click();
    cy.get('[data-testid="email-change-modal"]').should('be.visible');

    // Click cancel button
    cy.get('[data-testid="cancel-email-change"]').click();

    // Verify modal closes
    cy.get('[data-testid="email-change-modal"]').should('not.exist');

    // Verify we're back on profile page
    cy.get('[data-testid="profile-page"]').should('be.visible');
  });
});
